style.css:
@-moz-document domain("roblox.com") {
body {
        background: #ffcce6 url("https://wallpaperaccess.com/full/1598282.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Remove Roblox default gray backgrounds */
    #app-container,
    .container,
    .content,
    .page-content,
    .game-page,
    .profile-header,
    .section,
    .menu-container,
    .navbar,
    .rbx-header,
    .rbx-body,
    .content,
    .container-fluid,
    .col-xs-12,
    .col-sm-12,
    .col-md-12,
    .item-card-container,
    .section-content,
    .roblox-container {
        background: transparent !important;
    }

    /* Make cards/panels see-through */
    .card, .panel, .game-card, .profile-card {
        background-color: rgba(255, 255, 255, 0.2) !important;
        border: none !important;
    }

    /* Sidebar (dark menu on left) semi-transparent */
    .left-col, .rbx-left-col {
        background-color: rgba(0, 0, 0, 0.5) !important;
    }

    /* Top navbar semi-transparent */
    .rbx-navbar {
        background-color: rgba(255, 192, 203, 0.6) !important;
        backdrop-filter: blur(6px) !important;
    }

    /* Text colors for readability */
    body, div, span, p, a, h1, h2, h3, h4, h5, h6 {
        color: #fff !important;
    }

    a:hover {
        color: #ff99cc !important;
    }
}
